<p><a href="<?= h(url('download',['id'=>$r['document_id'],'v'=>$r['document_revision']])) ?>">Основной PDF v<?= h($r['document_revision']) ?></a> · <a href="<?= h(url('document',['id'=>$r['document_id']])) ?>">История исходного документа</a></p><code><?= h($r['document_hash']) ?></code>
