<?php if($draft&&$writable&&$pdfs): ?><form method="post" class="formgrid"><?php $hidden('contract.attach') ?><label>Приложение<select name="document"><?php selectOptions($pdfs) ?></select></label><label>Название<input name="label" maxlength="180" required></label><button>Добавить</button></form><?php endif ?>
<?php if(isset($activationEvidence[$r['id']])): $ev=$activationEvidence[$r['id']];$delta=json_decode($ev['terms_snapshot'],true,512,JSON_THROW_ON_ERROR); ?><h3>Зафиксированные изменения условий</h3><p>Полномочия: #<?= h($ev['seller_authority_id']) ?> / #<?= h($ev['buyer_authority_id']) ?>. Предыдущая редакция: <?= h($ev['previous_revision_id']??'нет') ?>.</p><?php elseif($draft): $delta=contractTermsDelta($active,$r); ?><h3>Предлагаемые изменения условий</h3><?php else: $delta=null; ?><p>Историческая редакция: доказательства проверки полномочий не зарегистрированы в версии 1.6.2.</p><?php endif ?>
<?php if($delta): ?><div class="tablewrap"><table><thead><tr><th>Условие</th><th>До</th><th>После</th></tr></thead><tbody><?php foreach(['currency'=>'Валюта','amount_minor'=>'Цена','signed_on'=>'Подписан','starts_on'=>'Начало','ends_on'=>'Окончание','notice_on'=>'Уведомление','renewal_terms'=>'Продление'] as $k=>$label): ?><tr><td><?= h($label) ?></td><td><?= h($delta['before']===null?'—':($k==='amount_minor'?money($delta['before'][$k]):$delta['before'][$k])) ?></td><td><?= h($k==='amount_minor'?money($delta['after'][$k]):$delta['after'][$k]) ?></td></tr><?php endforeach ?></tbody></table></div><p>Изменение цены: <?= h($delta['price_delta_minor']===null?'не сопоставляется':money($delta['price_delta_minor']).' '.$r['currency']) ?>. Счета и платежи не изменяются автоматически.</p><?php endif ?>
<?php if($draft&&$owner): ?><form method="post" class="formgrid"><?php $hidden('contract.activate') ?><?php foreach(['seller'=>'Наш подписант','buyer'=>'Подписант контрагента'] as $side=>$label): ?><label><?= h($label) ?><select name="<?= h($side) ?>_authority_id" required><option value="">Выберите полномочия</option><?php foreach($authorities as $a): try{contractAuthorityCheck($a,$r,$side);}catch(Problem $e){continue;} ?><option value="<?= h($a['id']) ?>">#<?= h($a['id'].' · '.$a['signer'].' · '.$a['basis']) ?></option><?php endforeach ?></select></label><?php endforeach ?><label><input type="checkbox" name="confirm_terms" value="1" required> Подтверждаю цену, валюту, сроки и проверку полномочий обеих сторон</label><label>Основание (подписанный документ, подтверждение полномочий)<input name="reason" required maxlength="500"></label><button>Зафиксировать вступление в силу</button></form><?php endif ?></details><?php endforeach ?></section>
<section class="panel"><h2>Контрольные задачи</h2><p>Срок договора является источником истины. Завершение задачи не закрывает обязательство. Задачи старых редакций остаются в истории.</p><?php $obligationStates=array_column($obligations,'state','id');$controlObligations=[];foreach($controls as $ctrl): if($ctrl['obligation_id']!==null)$controlObligations[$ctrl['obligation_id']]=true;$current=$ctrl['kind']==='obligation'?($obligationStates[$ctrl['obligation_id']]??'')==='open':($active&&(int)$active['id']===(int)$ctrl['revision_id']); ?><p><?= h(['notice'=>'Уведомление','expiry'=>'Окончание','obligation'=>'Исполнение'][$ctrl['kind']]) ?> · <?= h($ctrl['due_on']) ?> · <?php if($canWork): ?><a href="<?= h(url('task',['id'=>$ctrl['task_id']])) ?>">Задача #<?= h($ctrl['task_id']) ?></a><?php else: ?>Задача #<?= h($ctrl['task_id']) ?><?php endif ?> · <?= h($ctrl['task_state']) ?><?= !$current?' · историческая':($ctrl['due_on']<$today?' · срок прошёл':'') ?><?= $ctrl['task_due']!==$ctrl['due_on']?' · срок задачи отличается':'' ?></p><?php endforeach ?></section>
<section class="panel"><h2>Обязательства</h2><?php if($writable&&$active): ?><form method="post" class="formgrid"><?php $hidden('contract.obligation') ?><label>Обязательство<input name="title" maxlength="180" required></label><label>Срок<input name="due_on" type="date" required></label><?php if($owner): ?><label>Счёт (необязательно)<select name="invoice_id"><option value="">Нет</option><?php selectOptions($invoiceOptions) ?></select></label><label>Или план платежа<select name="plan_id"><option value="">Нет</option><?php selectOptions($planOptions) ?></select></label><p>Только один источник; связь не создаёт платежей.</p><?php endif ?><button>Добавить обязательство</button></form><?php endif ?>
<?php foreach($obligations as $o): ?><details open><summary><?= h($o['title']) ?> · <?= h($o['due_on']) ?> · <?= h(['open'=>'Открыто','completed'=>'Исполнено','cancelled'=>'Отменено'][$o['state']]) ?><?= $o['state']==='open'&&$o['due_on']<$today?' · просрочено':'' ?></summary><?php if($o['invoice_id']||$o['plan_id']): ?><p>Финансовая связь: <?php if($finance):$s=$o['settlement']; ?><a href="<?= h($o['invoice_id']?url('invoices',['project'=>$p,'id'=>$o['invoice_id']]):url('economics',['project'=>$p])) ?>"><?= h($s['label']) ?></a> · остаток <?= h(money((int)$s['remaining']).' '.$s['currency']) ?> · <?= h($s['state']) ?><?= $o['state']==='completed'&&!$s['settled']?' · финансовое состояние изменилось, требуется сверка':'' ?><?php else: ?>Доступно финансовым ролям<?php endif ?></p><?php endif ?><?php if($o['decision_note']!==null): ?><p><?= h($o['decision_note']) ?> · #<?= h($o['decided_by']) ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$o['decided_at'])) ?> UTC</p><?php endif ?><?php if($writable&&$o['state']==='open'&&!isset($controlObligations[$o['id']])): ?><form method="post"><?php $hidden('contract.control') ?><input type="hidden" name="obligation_id" value="<?= h($o['id']) ?>"><button>Создать контрольную задачу</button></form><?php endif ?><?php if($writable&&$o['state']==='open'&&($owner||(!$o['invoice_id']&&!$o['plan_id']))): ?><form method="post" class="formgrid"><?php $hidden('contract.decide') ?><input type="hidden" name="obligation_id" value="<?= h($o['id']) ?>"><label>Решение<select name="state"><option value="completed">Исполнено</option><option value="cancelled">Отменено</option></select></label><label>Подтверждение / причина<input name="reason" required maxlength="500"></label><button>Сохранить решение</button></form><?php endif ?></details><?php endforeach ?></section><?php endif ?>
<section class="panel"><h2>Реестр договоров</h2><div class="tablewrap"><table><thead><tr><th>Договор</th><th>Проект</th><th>Состояние</th><th>Уведомление</th><th>Окончание</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="<?= h(url('contracts',['project'=>$r['project_id'],'id'=>$r['id']])) ?>"><?= h($r['reference'].' · '.($r['active']??$r['latest'])['title']) ?></a></td><td><?= h($r['project_title']) ?></td><td><?= h(contractStatus($r['active'],$today)) ?></td><td><?= h($r['active']['notice_on']??'—') ?></td><td><?= h($r['active']['ends_on']??'—') ?></td></tr><?php endforeach ?></tbody></table></div><?php if($nextBefore): ?><a href="<?= h(url('contracts',['project'=>$p,'before'=>$nextBefore])) ?>">Следующая страница</a><?php endif ?></section>
